import { execFile } from 'child/promises'
import { promisify } from 'util'

const execFileAsync = promisify(execFile)

// 验证baseCmd是否为白名单命令
const allowedCommands = ['ls', 'cat', 'grep', 'find']
if (!allowedCommands.includes(baseCmd)) {
  throw new Error('命令不允许执行')
}

// 对参数进行验证和过滤
const sanitizedArgs = args.filter(arg => {
  // 移除空参数
  if (!arg || arg.trim() === '') return false
  // 防止路径遍历
  if (arg.includes('..')) return false
  // 防止特殊字符
  const dangerousChars = /[;|&$()`\\]/
  if (dangerousChars.test(arg)) return false
  return true
})

const { stdout } = await execFileAsync(baseCmd, sanitizedArgs)
